// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
// and future backends). One C++20 binary that selects a model (fast / cycle
// / hybrid), resolves engines at runtime, and either passes through to a single
// engine or orchestrates a hybrid round-trip.
//
// This file owns argument dispatch only: parse the CLI, route to a command.
// Each subcommand below resolves to its handler as its feature lands (F1-F13);
// until then it stubs out, keeping the command surface stable.
#include <cstdio>
#include <cstdlib>
#include <exception>
#include <string>
#include <string_view>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "repo_root.hpp"

namespace andes_sim {
int cmd_list(const Cli& cli);
int cmd_doctor(const Cli& cli);
int cmd_run(const Cli& cli);
}  // namespace andes_sim

namespace {

using andes_sim::Cli;
using andes_sim::is_dev_mode;

// Known command names. run/list/doctor have handlers (dispatched in main); the
// rest are stable slots for unfinished ROADMAP features, kept here so `find`
// routes them to the "not yet implemented" stub rather than "unknown command",
// while never appearing in `--help` (print_usage renders only the
// run/list/doctor blocks, so the product never advertises half-built work).
// Developer build/test/state-diff tooling lives in scripts/, not the binary.
// Display strings (briefs, modes, options) live in the help model below.
struct Subcommand {
  std::string_view name;
};

constexpr Subcommand kSubcommands[] = {
    {"run"},     {"list"},    {"doctor"}, {"profile"},
    {"cluster"}, {"archive"}, {"replay"}, {"estimate"},
};

const Subcommand* find(std::string_view name) {
  for (const Subcommand& s : kSubcommands)
    if (s.name == name) return &s;
  return nullptr;
}

// ---- help model: the user-facing surface rendered as a command tree --------
//
// `run`'s two subcommand groups -- the modes (the composition axis) ...
struct ModeRow {
  const char* name;
  const char* brief;
};
constexpr ModeRow kRunModes[] = {
    {"fast", "QEMU only -- functional, full speed"},
    {"cycle", "one cycle-accurate engine, from reset"},
    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
};

// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
struct TargetRow {
  const char* name;
  const char* brief;
  bool dev;
};
constexpr TargetRow kListTargets[] = {
    {"models", "the modes and their engines", false},
    {"engines", "discovered cycle-accurate engines", false},
    {"fixtures", "internal test ELFs (developer target)", true},
};

// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
// it is required); `dev` hides it unless ANDESIM_DEV is set.
struct OptRow {
  const char* flag;  // includes its own leading indent
  const char* tag;
  const char* brief;
  bool dev;
};
constexpr OptRow kRunOpts[] = {
    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run", false},
    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", false},
    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", false},
    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", false},
    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", false},
    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)", false},
    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)", false},
    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle", false},
    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", false},
    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", false},
    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle only; hybrid rejects -- args)", false},
};

// A major command line at column 0: `name   brief`.
void print_major(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "%-7s %s\n", name, brief);
}

// A subcommand/target line, indented two under its command: `  name   brief`.
void print_sub(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "  %-9s %s\n", name, brief);
}

// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
void print_opt(std::FILE* out, const OptRow& o) {
  if (o.tag[0])
    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
  else
    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
}

// `run`: major line, the mode subcommands, then the option list (dev options
// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
void print_run_block(std::FILE* out) {
  print_major(out, "run", "run one simulation");
  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
  std::fputs("\n", out);
  for (const OptRow& o : kRunOpts) {
    if (o.dev && !is_dev_mode()) continue;
    print_opt(out, o);
  }
}

void print_list_block(std::FILE* out) {
  print_major(out, "list", "list what is available");
  for (const TargetRow& t : kListTargets) {
    if (t.dev && !is_dev_mode()) continue;
    print_sub(out, t.name, t.brief);
  }
}

void print_doctor_block(std::FILE* out) {
  print_major(out, "doctor", "check toolchain + fixtures are present");
}

// Top-level `andesim --help`: the whole tree -- every major command, its
// subcommands, and run's full option list, so one screen shows everything.
void print_usage(std::FILE* out) {
  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
             out);
  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
             out);
  print_run_block(out);
  std::fputs("\n", out);
  print_list_block(out);
  std::fputs("\n", out);
  print_doctor_block(out);
  std::fputs(
      "\n'andesim run --help' / 'andesim list --help' for per-command "
      "detail.\n",
      out);
}

// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
  if (sc.name == "run") { print_run_block(out); return; }
  if (sc.name == "list") { print_list_block(out); return; }
  if (sc.name == "doctor") { print_doctor_block(out); return; }
  // A Hidden/unfinished command: a stable usage line, no advertised detail.
  std::fprintf(out, "usage: andesim %.*s [args...]\n",
               static_cast<int>(sc.name.size()), sc.name.data());
}

}  // namespace

int main(int argc, char** argv) {
  using namespace andes_sim;

  Cli cli = parse_cli(argc, argv);
  if (!cli.error.empty()) {
    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
    return 2;
  }

  if (cli.subcommand.empty()) {  // no command, or top-level -h
    if (cli.help) {
      print_usage(stdout);
      return 0;
    }
    print_usage(stderr);
    return 2;
  }

  const Subcommand* sc = find(cli.subcommand);
  if (!sc) {
    std::fprintf(stderr, "andesim: unknown command '%s'\n\n",
                 cli.subcommand.c_str());
    print_usage(stderr);
    return 2;
  }

  if (cli.help) {
    print_subcommand_help(*sc, stdout);
    return 0;
  }

  if (cli.subcommand == "list") return cmd_list(cli);
  if (cli.subcommand == "doctor") return cmd_doctor(cli);
  if (cli.subcommand == "run") return cmd_run(cli);

  // Remaining subcommands stub out until their feature lands. Resolve the repo
  // root so the discovery path stays live and observable.
  std::string root;
  try {
    root = repo_root().string();
  } catch (const std::exception& e) {
    root = std::string("<unknown: ") + e.what() + ">";
  }
  std::fprintf(stderr, "andesim %s: not yet implemented (repo root: %s)\n",
               cli.subcommand.c_str(), root.c_str());
  return 3;
}

// andesim command-line parsing.
//
// The grammar is deliberately tiny and stable across all subcommands:
//
//   andesim <cmd> [--mode M] [--engine E] [--trigger T] [positional...]
//                   [-- <verbatim engine args...>]
//
// The single most important rule is the `--` boundary: every token after the
// first `--` is captured verbatim into `passthrough` and is NOT interpreted by
// the framework. That is what lets `fast`/`cycle` forward an engine's whole
// native CLI (e.g. `-gdb tcp::1234 -S`) untouched, so users see one simulator.
#ifndef ANDESIM_CLI_HPP
#define ANDESIM_CLI_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct Cli {
  std::string subcommand;                 // e.g. "run", "list"; "" if none
  std::string model;                      // --mode fast|cycle|hybrid (field stays 'model': the concept, see list models)
  std::string engine;                     // --engine <id>
  std::string trigger;                    // --trigger marker|pc
  // Hybrid trigger args (empty => cmd_run applies the default). pc boundaries
  // are a symbol name or 0x address; the sizes stay strings here and are
  // parsed where they are used.
  std::string pc_start;                   // --pc-start (trigger pc)
  std::string pc_end;                     // --pc-end   (trigger pc)
  std::string mem_size;                   // --mem-size (guest memory; --mmap-size is a hidden alias)
  std::string kanata;                     // --kanata <file> (marker/pc ROI trace)
  std::string objdump;                    // --objdump <file> (kanata labels)
  std::vector<std::string> positional;    // non-flag framework args
  std::vector<std::string> passthrough;   // verbatim, everything after `--`
  bool help = false;                      // -h / --help (before `--`)
  bool dry_run = false;                   // --dry-run (build, run, test, ...)
  bool verify = false;                    // --verify (run --mode hybrid)
  bool gdb = false;                       // --gdb (fast: QEMU gdbstub; cycle: vsim JTAG + ICEman)
  std::string gdb_port;                   // --gdb-port (fast: default 1234; cycle: default 9104)
  bool has_passthrough = false;           // a `--` boundary was present
  std::string error;                      // non-empty => parse failed
};

// Parse argv[1..] (program name skipped). The vector overload is the testable
// core; the argv overload adapts it for main().
Cli parse_cli(const std::vector<std::string>& args);
Cli parse_cli(int argc, char** argv);

}  // namespace andes_sim

#endif  // ANDESIM_CLI_HPP
=====CLI.CPP=====
#include "cli.hpp"

namespace andes_sim {
namespace {

// Try to read an option's value at args[i]. Supports both `--flag value`
// (consumes the next token, advancing i) and `--flag=value`.
//   returns  1 = matched, `out` set
//            0 = this token is not `flag`
//           -1 = matched `--flag` but no value follows
int match_opt(const std::vector<std::string>& args, size_t& i,
              const std::string& flag, std::string& out) {
  const std::string& a = args[i];
  if (a == flag) {
    if (i + 1 >= args.size()) return -1;
    out = args[++i];
    return 1;
  }
  const std::string pfx = flag + "=";
  if (a.starts_with(pfx)) {
    out = a.substr(pfx.size());
    return 1;
  }
  return 0;
}

}  // namespace

Cli parse_cli(const std::vector<std::string>& args) {
  Cli c;
  if (args.empty()) return c;  // no subcommand; caller prints usage

  // First token is the subcommand, unless it is a top-level help request.
  if (args[0] == "-h" || args[0] == "--help") {
    c.help = true;
    return c;
  }
  c.subcommand = args[0];

  for (size_t i = 1; i < args.size(); ++i) {
    const std::string& a = args[i];

    if (a == "--") {  // the passthrough boundary: rest is verbatim
      c.has_passthrough = true;
      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
      break;
    }
    if (a == "-h" || a == "--help") {
      c.help = true;
      continue;
    }
    if (a == "--dry-run") {
      c.dry_run = true;
      continue;
    }
    if (a == "--verify") {
      c.verify = true;
      continue;
    }
    if (a == "--gdb") {
      c.gdb = true;
      continue;
    }

    const struct {
      const char* flag;
      std::string* out;
    } opts[] = {{"--mode", &c.model},
                {"--engine", &c.engine},
                {"--trigger", &c.trigger},
                {"--pc-start", &c.pc_start},
                {"--pc-end", &c.pc_end},
                {"--mem-size", &c.mem_size},
                {"--mmap-size", &c.mem_size},  // retired spelling, same knob
                {"--kanata", &c.kanata},
                {"--objdump", &c.objdump},
                {"--gdb-port", &c.gdb_port}};
    bool consumed = false;
    for (const auto& o : opts) {
      int r = match_opt(args, i, o.flag, *o.out);
      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
      if (r > 0) { consumed = true; break; }
    }
    if (consumed) continue;

    if (a.size() > 1 && a[0] == '-') {
      c.error = "unknown option: " + a;
      return c;
    }
    c.positional.push_back(a);
  }

  return c;
}

Cli parse_cli(int argc, char** argv) {
  std::vector<std::string> args;
  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
  return parse_cli(args);
}

}  // namespace andes_sim
=====ARGV.HPP=====
// Placeholder substitution for engine invoke templates -- the template-driven
// port of orchestrator/spawn.py (minus QEMU2). spawn.py hand-built each argv in
// Python; here the argv *shape* lives in each engine's `invoke` template (from
// `--describe`, see docs/engine_interface.md) and build_argv fills the
// {placeholders} from a context map. The framework thus keeps zero per-engine
// argv code: a new engine ships its own template.
#ifndef ANDESIM_ARGV_HPP
#define ANDESIM_ARGV_HPP

#include <cctype>
#include <cstring>
#include <map>
#include <string>
#include <vector>

namespace andes_sim {

// POSIX shell-quote one arg so a rendered command line is copy-pasteable. A
// token of only safe characters passes through; anything else (empty, spaces,
// quotes, globs) is wrapped in single quotes with embedded `'` escaped as
// '\''. Used by render_argv for the --dry-run command preview.
inline std::string shell_quote(const std::string& s) {
  if (!s.empty()) {
    bool safe = true;
    for (char c : s)
      if (!std::isalnum(static_cast<unsigned char>(c)) &&
          !std::strchr("_@%+=:,./-", c)) {
        safe = false;
        break;
      }
    if (safe) return s;
  }
  std::string out = "'";
  for (char c : s) out += (c == '\'') ? "'\\''" : std::string(1, c);
  out += "'";
  return out;
}

// Join an argv into one shell-quoted line (each token via shell_quote).
inline std::string render_argv(const std::vector<std::string>& argv) {
  std::string out;
  for (size_t i = 0; i < argv.size(); ++i) {
    if (i) out += ' ';
    out += shell_quote(argv[i]);
  }
  return out;
}

// Substitute every "{key}" in `tmpl`'s args with `ctx.at(key)`. A key may
// appear anywhere in an arg (so "mem-path={mmap},size={mmap_size}" expands in
// one arg) and more than once. Recognised keys come from `ctx`; a "{key}" with
// no matching ctx entry is an error (returns {} and sets `err`). On success
// `err` is cleared and the fully-resolved argv is returned.
std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
                                    const std::map<std::string, std::string>& ctx,
                                    std::string& err);

}  // namespace andes_sim

#endif  // ANDESIM_ARGV_HPP
=====ARGV.CPP=====
// Placeholder substitution for engine invoke templates. See argv.hpp.
#include "argv.hpp"

namespace andes_sim {
namespace {

// Expand every "{key}" in `s` from `ctx`. A "{" with no closing "}" is a
// literal. An unknown key sets `err` and returns false (out is undefined).
bool subst(const std::string& s, const std::map<std::string, std::string>& ctx,
           std::string& out, std::string& err) {
  out.clear();
  for (size_t i = 0; i < s.size();) {
    if (s[i] != '{') {
      out += s[i++];
      continue;
    }
    const size_t close = s.find('}', i + 1);
    if (close == std::string::npos) {  // unbalanced brace: keep literally
      out += s[i++];
      continue;
    }
    const std::string key = s.substr(i + 1, close - i - 1);
    const auto it = ctx.find(key);
    if (it == ctx.end()) {
      err = "unknown placeholder '{" + key + "}'";
      return false;
    }
    out += it->second;
    i = close + 1;
  }
  return true;
}

}  // namespace

std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
                                    const std::map<std::string, std::string>& ctx,
                                    std::string& err) {
  std::vector<std::string> out;
  out.reserve(tmpl.size());
  for (const std::string& arg : tmpl) {
    std::string filled;
    if (!subst(arg, ctx, filled, err)) return {};
    out.push_back(std::move(filled));
  }
  err.clear();
  return out;
}

}  // namespace andes_sim

// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andesim rebuild.
//
// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
#ifndef ANDESIM_ENGINE_REGISTRY_HPP
#define ANDESIM_ENGINE_REGISTRY_HPP

#include <filesystem>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "strutil.hpp"

namespace andes_sim {

// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
// agree -- a renamed literal would otherwise break find_engine() lookups only at
// run time.
inline constexpr const char* kQemuId64 = "qemu64";
inline constexpr const char* kQemuId32 = "qemu32";

struct Discovery {
  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
  std::vector<std::string> warnings;       // binaries that failed to describe
};

Discovery discover_engines();

// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
// <repo>/verilator/build.
std::filesystem::path vsim_scan_dir();

// The bundled qemu descriptor (no directory scan, no --describe subprocess).
// discover_engines() seeds the registry with it; `run --mode fast` resolves
// qemu through it directly, paying none of the Verilator-engine discovery cost.
// builtin_qemu_arch(xlen) builds the rv64 "qemu64" (xlen=64) or rv32 "qemu32"
// (xlen=32, qemu-system-riscv32); builtin_qemu() is the rv64 default.
EngineDescriptor builtin_qemu_arch(int xlen);
EngineDescriptor builtin_qemu();

// Rewrite a discovered engine's identity from the third-party simulator name to
// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
// dedup or shown anywhere, so every downstream consumer (list / --engine /
// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
// other backend (qemu, a drop-in alioth/sid) passes through untouched.
inline void normalize_engine_label(EngineDescriptor& d) {
  if (d.type == "verilator") d.type = "vsim";
  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
  // report it under their internal name "csr" via --describe. Speak the CLI's
  // vocabulary in list / doctor too, like verilator -> vsim above.
  for (std::string& t : d.triggers)
    if (t == "csr") t = "marker";
}

// Select the cycle-accurate engine for `run --mode cycle` from an
// already-discovered set (pure; spawns nothing). With `want_id` empty, default
// to the sole cycle-accurate engine -- erroring if there are none or more than
// one (ambiguous). With `want_id` set, that engine must exist and be
// cycle-accurate. Returns nullptr and sets `err` (naming the available
// cycle-accurate ids) on any failure; the returned pointer aliases into
// `engines`, so it must outlive the result.
inline const EngineDescriptor* resolve_accurate_engine(
    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
    std::string& err) {
  auto is_accurate = [](const EngineDescriptor& e) {
    return e.kind == "cycle-accurate";
  };
  auto accurate_ids = [&] {
    std::vector<std::string> ids;
    for (const EngineDescriptor& e : engines)
      if (is_accurate(e)) ids.push_back(e.id);
    return join(ids, ", ");
  };

  if (!want_id.empty()) {  // explicit --engine
    for (const EngineDescriptor& e : engines) {
      if (e.id != want_id) continue;
      if (is_accurate(e)) return &e;
      err = "engine '" + want_id + "' is " +
            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
            "; a cycle-accurate engine is required";
      return nullptr;
    }
    std::string have = accurate_ids();
    err = "no engine '" + want_id + "'" +
          (have.empty() ? " (no cycle-accurate engines found)"
                        : " (cycle-accurate engines: " + have + ")");
    return nullptr;
  }

  // No --engine: default to the sole cycle-accurate engine.
  const EngineDescriptor* sole = nullptr;
  int n = 0;
  for (const EngineDescriptor& e : engines)
    if (is_accurate(e)) { sole = &e; ++n; }
  if (n == 1) return sole;
  if (n == 0)
    err = "model cycle: no cycle-accurate engine found "
          "(build one with: scripts/build_all.sh vsim)";
  else
    err = "model cycle: multiple cycle-accurate engines; select one with "
          "--engine (have: " + accurate_ids() + ")";
  return nullptr;
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_REGISTRY_HPP
=====REGISTRY.CPP=====
#include "engine_registry.hpp"

#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>

#include <unistd.h>

#include "config_env.hpp"
#include "json.hpp"
#include "process.hpp"
#include "repo_root.hpp"

namespace fs = std::filesystem;

namespace andes_sim {

// The bundled functional engine(s). QEMU does not implement --describe, so the
// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
// scan whole-registry discovery would spawn.
EngineDescriptor builtin_qemu_arch(int xlen) {
  const bool rv32 = (xlen == 32);
  EngineDescriptor d;
  d.id = rv32 ? kQemuId32 : kQemuId64;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = xlen;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone"};
  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
    // (empty for marker), folded by leg_trigger_args (F9).
    d.roles.push_back("fast-leg");
    d.invoke.push_back(
        {"fast-leg",
         {"{bin}", "-object",
          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
          "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
          "enable=on,target=native", "-bios", "{elf}", "-plugin",
          "{plugin},outfile={state_out}{trigger}"}});
  }

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs the vplat fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv (rv64) / andes-a46mpv (rv32). We pass NO vlen --
  // the cpu model's own QEMU default applies, so both scalar and vector binaries
  // run out of the box; a user who needs a specific width passes it via the
  // post-`--` -cpu (e.g. -cpu andes-ax46mpv,vlen=512), which still wins.
  // run_passthrough fills {bin}/{elf}.
  const char* fast_cpu = rv32 ? "andes-a46mpv" : "andes-ax46mpv";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});

  const std::string sys =
      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
  if (const char* q = std::getenv(env); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / sys).string();
  else
    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
  return d;
}

// rv64 qemu (back-compat: the default functional engine and hybrid fast leg).
EngineDescriptor builtin_qemu() { return builtin_qemu_arch(64); }

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

std::string read_file(const fs::path& p) {
  std::ifstream f(p, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// Ask one binary to describe itself: try `<bin> --describe`, else read the
// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
// a human-readable note in `warn`.
bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
    json::Parsed p = json::parse(r.out);
    if (p.ok) {
      std::string err = descriptor_from_json(p.value, d);
      if (err.empty()) {
        d.bin_path = bin.string();
        d.source = "--describe";
        return true;
      }
      warn = bin.string() + ": --describe JSON invalid: " + err;
    } else {
      warn = bin.string() + ": --describe output is not JSON: " + p.error;
    }
  }

  fs::path sidecar = bin;
  sidecar += ".json";
  std::error_code ec;
  if (fs::exists(sidecar, ec)) {
    json::Parsed p = json::parse(read_file(sidecar));
    if (p.ok) {
      EngineDescriptor sd;
      std::string err = descriptor_from_json(p.value, sd);
      if (err.empty()) {
        sd.bin_path = bin.string();
        sd.source = "sidecar";
        d = std::move(sd);
        return true;
      }
      warn = sidecar.string() + ": invalid descriptor: " + err;
    } else {
      warn = sidecar.string() + ": not JSON: " + p.error;
    }
  }

  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
  return false;
}

// `prefix` filters candidate basenames; empty accepts any executable. The
// default verilator/build scan passes "sim_"; a user-curated engines dir passes
// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
// lives in the call site, not in this engine-agnostic scanner.
void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
              std::set<std::string>& seen) {
  std::error_code ec;
  if (!fs::is_directory(dir, ec)) return;

  std::vector<fs::path> entries;
  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
  std::sort(entries.begin(), entries.end());  // stable, deterministic order

  for (const fs::path& p : entries) {
    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
    if (!is_executable_file(p)) continue;
    EngineDescriptor d;
    std::string warn;
    if (describe_one(p, d, warn)) {
      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
    } else if (!warn.empty()) {
      out.warnings.push_back(warn);
    }
  }
}

}  // namespace

// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
// finds the external vsim without a prior `source ./setup.sh`; only an
// unset-everywhere value falls back to the legacy in-tree build dir.
fs::path vsim_scan_dir() {
  if (std::string v = config_env_value("VSIM_BIN_DIR"); !v.empty()) return v;
  return repo_root() / "verilator" / "build";
}

Discovery discover_engines() {
  Discovery out;
  std::set<std::string> seen;

  EngineDescriptor qemu = builtin_qemu();
  seen.insert(qemu.id);
  out.engines.push_back(std::move(qemu));

  // rv32 functional engine, listed alongside qemu so `list engines` shows both
  // (its binary is qemu-system-riscv32 under the same QEMU_BIN_DIR).
  EngineDescriptor qemu32 = builtin_qemu_arch(32);
  seen.insert(qemu32.id);
  out.engines.push_back(std::move(qemu32));

  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
    std::stringstream ss(env);
    std::string dir;
    while (std::getline(ss, dir, ':'))
      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
  } else {
    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
  }
  return out;
}

}  // namespace andes_sim

// EngineDescriptor: the parsed result of an engine's `--describe` (or its
// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
// future engines (alioth, sid) speak to join the framework -- see
// docs/engine_interface.md. The framework keeps zero per-engine code; every
// capability it needs comes from here.
#ifndef ANDESIM_ENGINE_DESCRIPTOR_HPP
#define ANDESIM_ENGINE_DESCRIPTOR_HPP

#include <string>
#include <string_view>
#include <vector>

#include "json.hpp"

namespace andes_sim {

// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
// plan executor (F6).
struct EngineInvoke {
  std::string role;
  std::vector<std::string> argv;
};

struct EngineDescriptor {
  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
  std::string type;                     // qemu | verilator | alioth | sid
  std::string kind;                     // functional | cycle-accurate
  long vlen = 0;                        // RVV params; 0 = not reported
  long dlen = 0;
  long elen = 0;
  long xlen = 0;
  std::vector<std::string> triggers;    // marker | pc
  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
  std::vector<std::string> andes_csrs;  // Andes CSRs this engine implements; the
                                        // --verify gate (empty = compare all)
  std::vector<EngineInvoke> invoke;     // argv template per role
  std::string result;                   // stderr:<re> | state.mcycle

  // Filled by the registry, not present in the JSON:
  std::string bin_path;                 // resolved path to the binary
  std::string source;                   // built-in | --describe | sidecar

  const std::vector<std::string>* invoke_for(std::string_view role) const {
    for (const EngineInvoke& iv : invoke)
      if (iv.role == role) return &iv.argv;
    return nullptr;
  }
};

// Build a descriptor from parsed JSON. Returns "" on success or an error
// message naming the first problem (id and type are required).
inline std::string descriptor_from_json(const json::Value& v,
                                        EngineDescriptor& out) {
  if (!v.is_object()) return "descriptor is not a JSON object";

  const json::Value* id = v.find("id");
  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
  out.id = id->as_string();

  const json::Value* type = v.find("type");
  if (!type || !type->is_string()) return "missing string 'type'";
  out.type = type->as_string();

  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
  if (const json::Value* x = v.find("dlen")) out.dlen = x->as_int();
  if (const json::Value* x = v.find("elen")) out.elen = x->as_int();
  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
  if (const json::Value* x = v.find("andes_csrs"))
    out.andes_csrs = x->as_string_array();
  if (const json::Value* x = v.find("result")) out.result = x->as_string();

  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
    for (size_t k = 0; k < inv->keys.size(); ++k)
      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
  }
  return "";
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_DESCRIPTOR_HPP
=====CMD_LIST=====
// `andesim list fixtures|models|engines`.
//
// `list fixtures` is a faithful C++ port of the Python hsim `parse_fixtures`
// + `list_fixtures`, so its output stays byte-identical to the golden driver
// (the parity flywheel depends on this). `list models` is new surface (the
// composition axis that replaced the old `--mode`). `list engines` is a
// scaffold until runtime discovery lands in F2.
#include <algorithm>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "repo_root.hpp"
#include "strutil.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
  std::ifstream f(p);
  std::vector<std::string> lines;
  ok = static_cast<bool>(f);
  if (!ok) return lines;
  std::string line;
  while (std::getline(f, line)) lines.push_back(line);
  return lines;
}

// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
// `var` and `body` (the text after `=`, continuation backslash included).
bool parse_assignment(const std::string& line, std::string& var,
                      std::string& body) {
  const size_t n = line.size();
  if (n == 0) return false;
  char c0 = line[0];
  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
  size_t p = 0;
  while (p < n) {
    char c = line[p];
    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
    else break;
  }
  var = line.substr(0, p);
  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
  if (p < n && line[p] == ':') ++p;                          // :?
  if (p >= n || line[p] != '=') return false;                // =
  ++p;
  body = line.substr(p);
  return true;
}

struct Fixture {
  std::string name;
  std::string family;
};

// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
  static const std::pair<std::string, std::string> interesting[] = {
      {"RT_FIXTURES", "asm"},
      {"RT_C_FIXTURES", "c"},
      {"RT_C_V_FIXTURES", "c+rvv"},
      {"PROBE_V_FIXTURES", "probe"},
  };
  std::vector<Fixture> rows;
  std::set<std::string> seen;

  for (size_t k = 0; k < lines.size(); ++k) {
    std::string var, body;
    if (!parse_assignment(lines[k], var, body)) continue;
    std::string family;
    for (const auto& it : interesting)
      if (it.first == var) { family = it.second; break; }
    if (family.empty()) continue;

    // Splice continuation lines: a trailing backslash + newline becomes a space.
    size_t li = k;
    while (!body.empty() && body.back() == '\\') {
      body.pop_back();
      body.push_back(' ');
      if (++li < lines.size()) body += lines[li];
      else break;
    }

    std::istringstream iss(body);
    std::string name;
    while (iss >> name)
      if (seen.insert(name).second) rows.push_back({name, family});
  }

  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
  if (seen.insert("handoff_roundtrip").second)
    rows.push_back({"handoff_roundtrip", "asm"});

  return rows;
}

int list_fixtures() {
  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
  bool ok;
  std::vector<std::string> lines = read_lines(mk, ok);
  if (!ok) {
    std::fprintf(stderr, "andesim: missing %s\n", mk.c_str());
    return 2;
  }
  std::vector<Fixture> rows = parse_fixtures(lines);

  size_t width = 0;
  for (const Fixture& r : rows) width = std::max(width, r.name.size());

  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
  for (const Fixture& r : rows)
    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
  return 0;
}

int list_models() {
  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
  for (const Model& m : kModels) {
    wn = std::max(wn, m.name.size());
    we = std::max(we, m.engines.size());
  }
  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
              ljust("ENGINES", we).c_str());
  for (const Model& m : kModels)
    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
                ljust(std::string(m.engines), we).c_str(),
                std::string(m.notes).c_str());
  return 0;
}

int list_engines() {
  Discovery disc = discover_engines();

  // Columns describe engine identity only. Triggers are a hybrid-MODEL option
  // (see `list models` / `run --help`), not an engine attribute, so no TRIGGERS
  // column here.
  size_t we = 6, wt = 4, wk = 4;  // ENGINE, TYPE, KIND headers
  for (const EngineDescriptor& e : disc.engines) {
    we = std::max(we, e.id.size());
    wt = std::max(wt, e.type.size());
    wk = std::max(wk, e.kind.size());
  }

  // Hardware params from each engine's --describe; "-" = not reported.
  std::printf("%s  %s  %s  XLEN  VLEN  DLEN  ELEN\n",
              ljust("ENGINE", we).c_str(), ljust("TYPE", wt).c_str(),
              ljust("KIND", wk).c_str());
  for (const EngineDescriptor& e : disc.engines)
    std::printf("%s  %s  %s  %-4s  %-4s  %-4s  %-4s\n", ljust(e.id, we).c_str(),
                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
                vlen_str(e.xlen).c_str(), vlen_str(e.vlen).c_str(),
                vlen_str(e.dlen).c_str(), vlen_str(e.elen).c_str());

  // Binaries that could not self-describe are reported, never silently dropped.
  for (const std::string& w : disc.warnings)
    std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
  return 0;
}

}  // namespace

int cmd_list(const Cli& cli) {
  // `fixtures` lists internal test ELFs -- a developer target, gated behind
  // ANDESIM_DEV so the release product offers only user-facing models/engines.
  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
  if (cli.positional.empty()) {
    std::fprintf(stderr, "andesim list: expected one of %s\n", targets);
    return 2;
  }
  const std::string& t = cli.positional[0];
  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
  if (t == "models") return list_models();
  if (t == "engines") return list_engines();
  std::fprintf(stderr, "andesim list: unknown target '%s' (want %s)\n",
               t.c_str(), targets);
  return 2;
}

}  // namespace andes_sim

