// Small text helpers shared across the command renderers (list, doctor).
// Header-only; no dependencies beyond the standard library.
#ifndef ANDESIM_STRUTIL_HPP
#define ANDESIM_STRUTIL_HPP

#include <string>
#include <vector>

namespace andes_sim {

// Left-justify `s` to width `w` (pad with spaces; never truncate).
inline std::string ljust(std::string s, size_t w) {
  if (s.size() < w) s.append(w - s.size(), ' ');
  return s;
}

// Join `v` with `sep` between elements.
inline std::string join(const std::vector<std::string>& v, const char* sep = ",") {
  std::string s;
  for (size_t k = 0; k < v.size(); ++k) {
    if (k) s += sep;
    s += v[k];
  }
  return s;
}

// Engine HW width param (VLEN/DLEN/ELEN/XLEN) for display: a positive width
// prints as its number, 0/absent "-".
inline std::string vlen_str(long v) {
  return v > 0 ? std::to_string(v) : std::string("-");
}

}  // namespace andes_sim

#endif  // ANDESIM_STRUTIL_HPP
---MODELS-FINAL---
// The three models andesim composes from engines. A model says *which*
// engines run and *how* they combine; the concrete engine(s) are resolved
// separately (built-in qemu, or a discovered verilator:<cfg>).
//
//   fast      = QEMU alone (functional), transparent passthrough.
//   cycle     = one Verilator alone, pure from reset, transparent passthrough.
//   hybrid    = QEMU fast-forwards, Verilator measures the ROI (+ a trigger).
#ifndef ANDESIM_MODELS_HPP
#define ANDESIM_MODELS_HPP

#include <string_view>

namespace andes_sim {

struct Model {
  std::string_view name;
  std::string_view engines;  // engine composition, for `list models`
  std::string_view notes;
};

inline constexpr Model kModels[] = {
    {"fast", "qemu64 | qemu32", "functional"},
    {"cycle", "vsim:<cfg>", "cycle-accurate"},
    {"hybrid", "qemu64 -> vsim",
     "QEMU fast-forwards, vsim measures the ROI; "
     "pick --trigger marker|pc"},
};

inline const Model* find_model(std::string_view name) {
  for (const Model& m : kModels)
    if (m.name == name) return &m;
  return nullptr;
}

}  // namespace andes_sim

#endif  // ANDESIM_MODELS_HPP
