// Repo-root discovery for andesim.
//
// The driver shells out to repo scripts (scripts/build_*.sh), reads fixtures
// (tests/fixtures/), and scans the engines dir -- all relative to the repo
// root. The root is found from the executable's own location via
// /proc/self/exe, so it works regardless of the caller's CWD and for both
// layouts: build/andesim during development and a repo-root andesim after
// the F14 swap.
#ifndef ANDESIM_REPO_ROOT_HPP
#define ANDESIM_REPO_ROOT_HPP

#include <climits>
#include <filesystem>
#include <stdexcept>
#include <string>

#include <unistd.h>

namespace andes_sim {

// Absolute path to this executable, resolved through /proc/self/exe.
inline std::filesystem::path exe_path() {
  char buf[PATH_MAX];
  ssize_t n = ::readlink("/proc/self/exe", buf, sizeof(buf) - 1);
  if (n < 0) throw std::runtime_error("readlink(/proc/self/exe) failed");
  buf[n] = '\0';
  return std::filesystem::path(buf);
}

// Nearest ancestor of the executable that looks like this repo's root,
// identified by two stable markers that travel together: the setup.sh build
// entry point and the shared ABI header. Throws if no such ancestor exists.
inline std::filesystem::path repo_root() {
  namespace fs = std::filesystem;
  // Pure function of /proc/self/exe and the on-disk layout, both stable for the
  // life of the process, so compute it once. (If discovery fails the throwing
  // initializer just re-runs on the next call.)
  static const fs::path root = [] {
    fs::path start = exe_path().parent_path();
    for (fs::path p = start;; p = p.parent_path()) {
      if (fs::exists(p / "setup.sh") &&
          fs::exists(p / "include" / "hybrid" / "state_abi.h"))
        return p;
      if (p == p.root_path()) break;
    }
    throw std::runtime_error("repo root not found above " + start.string());
  }();
  return root;
}

// The bundled QEMU plugin's default location under the repo root. Callers
// that honor a $VSIM_PLUGIN override apply it themselves (cmd_doctor's
// artifact table, run_plan's resolve_plugin); this is the single source for
// the in-repo path.
inline std::filesystem::path default_plugin_path() {
  return repo_root() / "qemu_plugin" / "libhybrid_handoff.so";
}

}  // namespace andes_sim

#endif  // ANDESIM_REPO_ROOT_HPP

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <functional>
#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
int fork_background(const std::vector<std::string>& argv);

// Run argv with BOTH stdout and stderr captured (separate pipes) and stdin
// inherited, streaming each complete line to `on_line(stream, line)` as it
// arrives -- stream is 1 (stdout) or 2 (stderr), line excludes the trailing
// newline. The callback owns presentation (it decides what to write to the real
// streams), so this is the filtered counterpart to exec_passthrough: same "run
// to completion, no timeout, propagate exit code" contract, but the parent sees
// every line. A final unterminated line is delivered too. Returns the child's
// exit code, 128+signal if signalled, or -1 on spawn failure / empty argv.
int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int stream, std::string_view line)>& on_line);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP
