  {
    Cli c = parse_cli({"run", "-h"});
    CHECK(c.subcommand == "run");
    CHECK(c.help);
  }
  {
    Cli c = parse_cli({"list", "--help"});
    CHECK(c.subcommand == "list");
    CHECK(c.help);
  }

  // Top-level help: no subcommand.
  {
    Cli c = parse_cli({"-h"});
    CHECK(c.subcommand.empty());
    CHECK(c.help);
  }

  // list positional target.
  {
    Cli c = parse_cli({"list", "fixtures"});
    CHECK(c.subcommand == "list");
    CHECK(c.positional.size() == 1 && c.positional[0] == "fixtures");
  }

  // The icount/warmup knobs were removed: --qemu-icount / --vsim-icount /
  // --vsim-warmup-icount are now unknown options.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--qemu-icount", "10",
                       "prog.elf"});
    CHECK(!c.error.empty());
    Cli d = parse_cli({"run", "--mode", "hybrid", "--vsim-icount", "10",
                       "prog.elf"});
    CHECK(!d.error.empty());
    Cli e = parse_cli({"run", "--mode", "hybrid", "--vsim-warmup-icount", "500",
                       "prog.elf"});
    CHECK(!e.error.empty());
  }

  // --what was a placeholder for a never-wired `build` subcommand: it parsed
  // but no command read it, so it silently swallowed its value everywhere.
  // Removed -- now an unknown option like any other.
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--what", "driver", "prog.elf"});
    CHECK(!c.error.empty());
  }

  // Unknown option before `--` is an error.
  {
    Cli c = parse_cli({"run", "--bogus"});
    CHECK(!c.error.empty());
  }

  // A selection flag with no value is an error.
  {
    Cli c = parse_cli({"run", "--mode"});
    CHECK(!c.error.empty());
  }

  // --model was renamed to --mode (clean break): the old spelling no longer
  // parses -- it falls through to the unknown-option error.
  {
    Cli c = parse_cli({"run", "--model", "fast", "prog.elf"});
    CHECK(!c.error.empty());
  }

  return andes_sim::test::report("cli parse");
}

// The three models andesim composes from engines. A model says *which*
// engines run and *how* they combine; the concrete engine(s) are resolved
// separately (built-in qemu, or a discovered verilator:<cfg>).
//
//   fast      = QEMU alone (functional), transparent passthrough.
//   cycle     = one Verilator alone, pure from reset, transparent passthrough.
//   hybrid    = QEMU fast-forwards, Verilator measures the ROI (+ a trigger).
#ifndef ANDESIM_MODELS_HPP
#define ANDESIM_MODELS_HPP

#include <string_view>

namespace andes_sim {

struct Model {
  std::string_view name;
  std::string_view engines;  // engine composition, for `list models`
  std::string_view notes;
};

inline constexpr Model kModels[] = {
    {"fast", "qemu", "functional"},
    {"cycle", "vsim:<cfg>", "cycle-accurate"},
    {"hybrid", "qemu -> vsim",
     "QEMU fast-forwards, vsim measures the ROI; "
     "pick --trigger marker|pc"},
};

inline const Model* find_model(std::string_view name) {
  for (const Model& m : kModels)
    if (m.name == name) return &m;
  return nullptr;
}

}  // namespace andes_sim

#endif  // ANDESIM_MODELS_HPP

// EngineDescriptor: the parsed result of an engine's `--describe` (or its
// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
// future engines (alioth, sid) speak to join the framework -- see
// docs/engine_interface.md. The framework keeps zero per-engine code; every
// capability it needs comes from here.
#ifndef ANDESIM_ENGINE_DESCRIPTOR_HPP
#define ANDESIM_ENGINE_DESCRIPTOR_HPP

#include <string>
#include <string_view>
#include <vector>

#include "json.hpp"

namespace andes_sim {

// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
// plan executor (F6).
struct EngineInvoke {
  std::string role;
  std::vector<std::string> argv;
};

struct EngineDescriptor {
  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
  std::string type;                     // qemu | verilator | alioth | sid
  std::string kind;                     // functional | cycle-accurate
  long vlen = 0;                        // 0 = not reported
  long xlen = 0;
  std::vector<std::string> triggers;    // marker | pc
  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
  std::vector<EngineInvoke> invoke;     // argv template per role
  std::string result;                   // stderr:<re> | state.mcycle

  // Filled by the registry, not present in the JSON:
  std::string bin_path;                 // resolved path to the binary
  std::string source;                   // built-in | --describe | sidecar

  const std::vector<std::string>* invoke_for(std::string_view role) const {
    for (const EngineInvoke& iv : invoke)
      if (iv.role == role) return &iv.argv;
    return nullptr;
  }
};

// Build a descriptor from parsed JSON. Returns "" on success or an error
// message naming the first problem (id and type are required).
inline std::string descriptor_from_json(const json::Value& v,
                                        EngineDescriptor& out) {
  if (!v.is_object()) return "descriptor is not a JSON object";

  const json::Value* id = v.find("id");
  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
  out.id = id->as_string();

  const json::Value* type = v.find("type");
  if (!type || !type->is_string()) return "missing string 'type'";
  out.type = type->as_string();

  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
  if (const json::Value* x = v.find("result")) out.result = x->as_string();

  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
    for (size_t k = 0; k < inv->keys.size(); ++k)
      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
  }
  return "";
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_DESCRIPTOR_HPP

// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andesim rebuild.
//
// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
#ifndef ANDESIM_ENGINE_REGISTRY_HPP
#define ANDESIM_ENGINE_REGISTRY_HPP

#include <filesystem>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "strutil.hpp"

namespace andes_sim {

// Built-in functional engine id. Declared once here so builtin_qemu and every
// lookup agree -- a renamed literal would otherwise break find_engine()
// lookups only at run time.
inline constexpr const char* kQemuId = "qemu";

struct Discovery {
  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
  std::vector<std::string> warnings;       // binaries that failed to describe
};

Discovery discover_engines();

// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
// <repo>/verilator/build.
std::filesystem::path vsim_scan_dir();

// The bundled qemu descriptor (no directory scan, no --describe subprocess).
// discover_engines() seeds the registry with it; `run --mode fast` resolves
// qemu through it directly, paying none of the Verilator-engine discovery cost.
EngineDescriptor builtin_qemu();

// Rewrite a discovered engine's identity from the third-party simulator name to
// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
// dedup or shown anywhere, so every downstream consumer (list / --engine /
// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
// other backend (qemu, a drop-in alioth/sid) passes through untouched.
inline void normalize_engine_label(EngineDescriptor& d) {
  if (d.type == "verilator") d.type = "vsim";
  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
  // report it under their internal name "csr" via --describe. Speak the CLI's
  // vocabulary in list too, like verilator -> vsim above.
  for (std::string& t : d.triggers)
    if (t == "csr") t = "marker";
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_REGISTRY_HPP

#include "engine_registry.hpp"

#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>

#include <unistd.h>

#include "config_env.hpp"
#include "json.hpp"
#include "process.hpp"
