namespace fs = std::filesystem;

namespace andes_sim {

// The bundled functional engine. QEMU does not implement --describe, so the
// descriptor is built in. The standalone (model=fast) run uses qemu's OWN
// default behavior as far as possible -- the user's post-`--` args (incl. an
// explicit -cpu) still win; only the hybrid fast-leg pins a -cpu. Binary path
// honors $VSIM_QEMU, then $QEMU_BIN_DIR (env or config.env), then the legacy
// in-tree build. Exposed (engine_registry.hpp) so `run --mode fast` resolves
// qemu directly, skipping the per-engine --describe scan whole-registry
// discovery would spawn.
EngineDescriptor builtin_qemu() {
  EngineDescriptor d;
  d.id = kQemuId;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = 64;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone", "fast-leg"};
  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
  // into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out} are
  // filled by the plan executor (F6); {trigger} is the plugin comma-suffix
  // (empty for marker), folded by leg_trigger_args (F9).
  d.invoke.push_back(
      {"fast-leg",
       {"{bin}", "-object",
        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
        "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
        "enable=on,target=native", "-bios", "{elf}", "-plugin",
        "{plugin},outfile={state_out}{trigger}"}});

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs C-runtime fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv. We pass NO vlen -- the cpu model's own QEMU
  // default applies, so both scalar and vector binaries run out of the box; a
  // user who needs a specific width passes it via the post-`--` -cpu (e.g.
  // -cpu andes-ax46mpv,vlen=512), which still wins. run_passthrough fills
  // {bin}/{elf}.
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax46mpv",
        "-nographic", "-semihosting-config", "enable=on,target=native",
        "-bios", "{elf}"}});

  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / "qemu-system-riscv64").string();
  else
    d.bin_path =
        (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
  return d;
}

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

std::string read_file(const fs::path& p) {
  std::ifstream f(p, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// Ask one binary to describe itself: try `<bin> --describe`, else read the
// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
// a human-readable note in `warn`.
bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
    json::Parsed p = json::parse(r.out);
    if (p.ok) {
      std::string err = descriptor_from_json(p.value, d);
      if (err.empty()) {
        d.bin_path = bin.string();
        d.source = "--describe";
        return true;
      }
      warn = bin.string() + ": --describe JSON invalid: " + err;
    } else {
      warn = bin.string() + ": --describe output is not JSON: " + p.error;
    }
  }

  fs::path sidecar = bin;
  sidecar += ".json";
  std::error_code ec;
  if (fs::exists(sidecar, ec)) {
    json::Parsed p = json::parse(read_file(sidecar));
    if (p.ok) {
      EngineDescriptor sd;
      std::string err = descriptor_from_json(p.value, sd);
      if (err.empty()) {
        sd.bin_path = bin.string();
        sd.source = "sidecar";
        d = std::move(sd);
        return true;
      }
      warn = sidecar.string() + ": invalid descriptor: " + err;
    } else {
      warn = sidecar.string() + ": not JSON: " + p.error;
    }
  }

  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
  return false;
}

// `prefix` filters candidate basenames; empty accepts any executable. The
// default verilator/build scan passes "sim_"; a user-curated engines dir passes
// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
// lives in the call site, not in this engine-agnostic scanner.
void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
              std::set<std::string>& seen) {
  std::error_code ec;
  if (!fs::is_directory(dir, ec)) return;

  std::vector<fs::path> entries;
  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
  std::sort(entries.begin(), entries.end());  // stable, deterministic order

  for (const fs::path& p : entries) {
    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
    if (!is_executable_file(p)) continue;
    EngineDescriptor d;
    std::string warn;
    if (describe_one(p, d, warn)) {
      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
    } else if (!warn.empty()) {
      out.warnings.push_back(warn);
    }
  }
}

}  // namespace

// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
// finds the external vsim without a prior `source ./setup.sh`; only an
// unset-everywhere value falls back to the legacy in-tree build dir.
fs::path vsim_scan_dir() {
  if (std::string v = config_env_value("VSIM_BIN_DIR"); !v.empty()) return v;
  return repo_root() / "verilator" / "build";
}

Discovery discover_engines() {
  Discovery out;
  std::set<std::string> seen;

  EngineDescriptor qemu = builtin_qemu();
  seen.insert(qemu.id);
  out.engines.push_back(std::move(qemu));

  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
    std::stringstream ss(env);
    std::string dir;
    while (std::getline(ss, dir, ':'))
      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
  } else {
    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
  }
  return out;
}

}  // namespace andes_sim

// EX1: discover_engines() picks its vsim scan dir from $VSIM_BIN_DIR (the
// external prebuilt vsim build, mirroring $QEMU_BIN_DIR), and -- when the env is
// unset -- from the VSIM_BIN_DIR assignment in config.env, so `./andesim` finds
// the external vsim without a prior `source ./setup.sh`. Pure environment/file
// logic, no subprocess.
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>

#include "config_env.hpp"
#include "engine_registry.hpp"
#include "repo_root.hpp"
#include "test_check.hpp"

namespace fs = std::filesystem;

int main() {
  using namespace andes_sim;

  // --- vsim_scan_dir honors $VSIM_BIN_DIR (external, like $QEMU_BIN_DIR) ---
  setenv("VSIM_BIN_DIR", "/opt/vsim_andesim/build", /*overwrite=*/1);
  CHECK(vsim_scan_dir() == fs::path("/opt/vsim_andesim/build"));
  unsetenv("VSIM_BIN_DIR");

  // --- config_env_value: env first, else the KEY= line in the config file ---
  fs::path cfg = fs::temp_directory_path() /
                 ("andesim_cfgenv_test_" + std::to_string(::getpid()) + ".env");
  {
    std::ofstream f(cfg);
    f << "# per-host config\n"
         "HYBRID_TOOLCHAIN=/opt/tc\n"
         "  VSIM_BIN_DIR=/from/config/build\n";  // leading ws tolerated
  }

  // env unset -> value comes from the config file
  unsetenv("VSIM_BIN_DIR");
  CHECK(config_env_value("VSIM_BIN_DIR", cfg) == "/from/config/build");

  // env set (non-empty) wins over the config file
  setenv("VSIM_BIN_DIR", "/from/env/build", /*overwrite=*/1);
  CHECK(config_env_value("VSIM_BIN_DIR", cfg) == "/from/env/build");
  unsetenv("VSIM_BIN_DIR");

  // a key absent from both env and file -> empty
  CHECK(config_env_value("NO_SUCH_KEY", cfg).empty());

  // a missing config file is not an error -> empty (env still consulted first)
  CHECK(config_env_value("VSIM_BIN_DIR", "/no/such/file.env").empty());

  // builtin_qemu resolves its binary the same way: $VSIM_QEMU (the explicit
  // binary) wins over the QEMU_BIN_DIR / default fallback.
  setenv("VSIM_QEMU", "/opt/qemu/qemu-system-riscv64", /*overwrite=*/1);
  CHECK(builtin_qemu().bin_path == "/opt/qemu/qemu-system-riscv64");
  unsetenv("VSIM_QEMU");

  // The built-in functional engine: id, xlen, and binary.
  const EngineDescriptor q = builtin_qemu();
  CHECK(q.id == "qemu");
  CHECK(q.xlen == 64);
  CHECK(q.bin_path.ends_with("qemu-system-riscv64"));
  // model=fast pins a concrete andes core (andes_ae350's generic default -cpu
  // hangs C-runtime fixtures): the vector-capable ax46mpv. andesim passes NO
  // vlen -- the cpu model's own QEMU default applies; a user who wants a
  // specific width passes it via the post-`--` -cpu, which still wins.
  auto fast_cpu = [](const EngineDescriptor& e) -> std::string {
    const std::vector<std::string>* st = e.invoke_for("standalone");
    if (!st) return "";
    for (std::size_t i = 0; i + 1 < st->size(); ++i)
      if ((*st)[i] == "-cpu") return (*st)[i + 1];
    return "";
  };
  CHECK(fast_cpu(q) == "andes-ax46mpv");
  CHECK(q.invoke_for("fast-leg") != nullptr);

  // normalize_engine_label speaks the CLI's vocabulary: an engine that reports
  // its marker delimiter under the internal name "csr" (via --describe) is shown
  // as "marker" (what `--trigger marker` expects), like verilator -> vsim.
  {
    EngineDescriptor d;
    d.type = "verilator";
    d.id = "verilator:cfg";
    d.triggers = {"csr", "pc"};
    normalize_engine_label(d);
    CHECK(d.type == "vsim");
    CHECK(d.id == "vsim:cfg");
    CHECK((d.triggers == std::vector<std::string>{"marker", "pc"}));
  }

  std::remove(cfg.c_str());
  return andes_sim::test::report("engine-registry");
}

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

#include "process.hpp"

#include <cerrno>
#include <ctime>

#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <sys/wait.h>
#include <unistd.h>

namespace andes_sim {
namespace {

long now_ms() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
}

}  // namespace

RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
  RunResult r;
  if (argv.empty()) {
    r.spawn_failed = true;
    return r;
  }

  int fds[2];
  if (pipe(fds) != 0) {
    r.spawn_failed = true;
    return r;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(fds[0]);
    close(fds[1]);
    r.spawn_failed = true;
    return r;
  }

  if (pid == 0) {  // child
    close(fds[0]);
    dup2(fds[1], STDOUT_FILENO);
    int devnull = open("/dev/null", O_RDWR);
    if (devnull >= 0) {
      dup2(devnull, STDIN_FILENO);
      dup2(devnull, STDERR_FILENO);
      if (devnull > 2) close(devnull);
    }
    close(fds[1]);
    std::vector<char*> cargv;
    cargv.reserve(argv.size() + 1);
    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
    cargv.push_back(nullptr);
    execvp(cargv[0], cargv.data());
    _exit(127);  // exec failed
  }

  // parent
  close(fds[1]);
  int rfd = fds[0];
  const long deadline = now_ms() + timeout_ms;
  char buf[4096];

  while (true) {
    long remaining = deadline - now_ms();
    if (remaining < 0) remaining = 0;
    struct pollfd pfd{rfd, POLLIN, 0};
    int pr = poll(&pfd, 1, static_cast<int>(remaining));
    if (pr < 0) {
      if (errno == EINTR) continue;
      break;
    }
    if (pr == 0) {  // timed out with no data ready
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
      ssize_t n = read(rfd, buf, sizeof(buf));
      if (n > 0) {
        r.out.append(buf, static_cast<size_t>(n));
      } else if (n == 0) {
        break;  // EOF: child closed stdout
      } else {
        if (errno == EINTR) continue;
        break;
      }
    }
    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
  }

  close(rfd);
  int status = 0;
  waitpid(pid, &status, 0);
  // rc stays -1 (the default) when timed out or abnormally terminated.
  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
  return r;
}

